pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Fund the contract with 1 ether
        vm.deal(address(c), 1 ether);
        // Owner (this test contract) calls withdrawAll to an arbitrary recipient
        address recipient = address(0x123);
        uint256 initialContractBalance = address(this).balance;
        bool success;
        try c.withdrawAll(recipient) {
            success = true;
        } catch {
            success = false;
        }
