pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Fund the contract with 1 ether
        vm.deal(address(c), 1 ether);
        // Prepare a non-owner account
        address nonOwner = address(0x1234);
        vm.deal(nonOwner, 0);
        // Non-owner attempts to withdraw all to themselves
        vm.prank(nonOwner);
        // The reference will revert (require owner); the bug will succeed
        bool ok;
        try c.withdrawAll(nonOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        // On the reference, ok == false (revert); on the bug, ok == true (no revert)
        // However we need to assert on the final state: reference retains balance, bug loses it
        // We'll assert that the contract balance after the call is 1 ether (reference behavior)
        // The bug would leave 0 ether
        assertTrue(address(c).balance == 1 ether);
    }
}

