// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Deploy a recipient contract that rejects all ETH transfers
        Rejector rejector = new Rejector();
        // Fund the contract with 1 wei
        vm.deal(address(c), 1 wei);
        // Attempt withdrawAll to the rejecting contract
        bool ok;
        try c.withdrawAll(address(rejector)) { ok = true; } catch { ok = false; }
        // Reference (transfer) reverts, so ok == false; buggy (send) returns false silently, so ok == true
        // Assert that the call reverted (reference behavior); the bug would make it pass
        assertTrue(!ok, "Reference should revert when sending to a contract that rejects transfers");
    }
}

contract Rejector {
    // Reject all incoming ETH
    receive() external payable {
        revert("I reject ETH");
    }
    fallback() external payable {
        revert("I reject ETH");
    }
}

